<script setup>
defineProps({coverage:{type:Object,required:true}});const emit=defineEmits(['create']);
</script>
<template><section aria-label="Pricing coverage review"><h4>Pricing coverage review</h4><p data-testid="pricing-coverage-summary" role="status">{{ coverage.overrideSheets }} override sheets · {{ coverage.fallbackSheets }} fallback sheets · {{ coverage.zeroRateSheets }} zero-rate sheets · {{ coverage.unusedOverrides.length }} unused overrides</p><p class="hint">Fallback and zero rates are advisory, not blockers. A zero price may be intentional. Creating an override copies the current effective price without changing the total.</p><button :disabled="!coverage.stocks.some(s=>s.source==='material')" @click="emit('create',coverage.stocks.filter(s=>s.source==='material'))">Create overrides for fallback stock</button><ul><li v-for="stock in coverage.stocks" :key="[stock.material,stock.thicknessMm,stock.stockLengthMm,stock.stockWidthMm].join(':')">{{ stock.material }} · {{ stock.thicknessMm.toFixed(3) }} mm · {{ stock.stockLengthMm }} × {{ stock.stockWidthMm }} mm · {{ stock.sheets }} sheets · {{ stock.source==='stock'?'stock override':'material fallback' }}{{ stock.unitCents===0?' · zero price':'' }}<button v-if="stock.source==='material'" @click="emit('create',[stock])">Create override for {{ stock.material }} {{ stock.thicknessMm.toFixed(3) }} mm {{ stock.stockLengthMm }} × {{ stock.stockWidthMm }}</button></li></ul><p v-if="!coverage.stocks.length" class="hint">No stock sheets in this revision.</p><ul v-if="coverage.unusedOverrides.length"><li v-for="(row,i) in coverage.unusedOverrides" :key="i">Unused: {{ row.material }} · {{ row.thicknessMm }} mm · {{ row.stockLengthMm }} × {{ row.stockWidthMm }} mm</li></ul></section></template>
